package i18n

// Collections (TEC-718): export labels and enum values. Kept in a file of
// its own and merged at init so parallel modules do not edit one map.
func init() {
	for k, v := range collectionsTR {
		trCatalog[k] = v
	}
	for k, v := range collectionsEN {
		enCatalog[k] = v
	}
}

